//! Parity tests for `query_df` (`tests/fixtures/query_df.json`, generated by
//! `tests/fixtures/gen_query_df.py`).

mod common;

use common::{cases, compare_frame, decode, decode_frame, load_fixture};
use meerschaum_kernel::query::{ParamValue, QueryOptions, query_df};
use serde_json::Value as J;

fn strings(j: &J) -> Option<Vec<String>> {
    j.as_array()
        .map(|a| a.iter().map(|v| v.as_str().unwrap().to_string()).collect())
}

#[test]
fn query_df_parity() {
    let fixture = load_fixture("query_df");
    let mut failures = Vec::new();
    let mut checked = 0;
    for case in cases(&fixture) {
        let kw = &case["kwargs"];
        let context = format!("{} {}", case["frame"], kw);
        let df = decode_frame(&case["input"]);
        let mut opts = QueryOptions {
            begin: kw.get("begin").map(decode),
            end: kw.get("end").map(decode),
            datetime_column: kw["datetime_column"].as_str().map(str::to_string),
            select_columns: strings(&kw["select_columns"]),
            omit_columns: strings(&kw["omit_columns"]),
            reset_index: kw["reset_index"].as_bool().unwrap_or(false),
            coerce_types: kw["coerce_types"].as_bool().unwrap_or(false),
            ..Default::default()
        };
        if let Some(params) = kw["params"].as_object() {
            for (k, v) in params {
                let p = match v.get("list") {
                    Some(J::Array(items)) => ParamValue::Many(items.iter().map(decode).collect()),
                    _ => ParamValue::One(decode(v)),
                };
                opts.params.insert(k.clone(), p);
            }
        }
        checked += 1;
        match (query_df(&df, &opts), case.get("ok")) {
            (Ok(out), Some(expected)) => {
                if let Err(m) = compare_frame(expected, &out.frame, &context) {
                    failures.push(m);
                }
                let expected_index: Vec<i64> = expected["index"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|v| v["v"].as_i64().unwrap())
                    .collect();
                let actual_index: Vec<i64> = out.index.iter().map(|i| *i as i64).collect();
                let expected_cols = expected["columns"].as_array().unwrap().len();
                if expected_cols > 0 && expected_index != actual_index {
                    failures.push(format!(
                        "{context}: index {actual_index:?} != {expected_index:?}"
                    ));
                }
            }
            (Err(_), None) => {}
            (Ok(_), None) => failures.push(format!("{context}: expected error {}", case["err"])),
            (Err(e), Some(_)) => failures.push(format!("{context}: unexpected error {e}")),
        }
    }
    assert!(checked > 60);
    if !failures.is_empty() {
        panic!(
            "{} query_df parity failures:\n{}",
            failures.len(),
            failures.join("\n")
        );
    }
}
